GameMode.update:
public update(gc: GameContainer): void {
        if (this.paused) {
            if (this.input.isPause()) {
                this.paused = false;
                this.main.currentSong?.resume();
            }
            this.main.resetNextFrameTime();
            return;
        } else if (this.input.isPause() && !this.stageCompletedFlag && this.playing && this.main.isSongPlaying()) {
            this.paused = true;
            this.main.playSound(this.main.pauseSound);
            this.main.currentSong?.pause();
            // Accepting Pause terminates this simulation tick, just like unpausing.
            this.main.resetNextFrameTime();
            return;
        }

        if (++this.waterAlphaIndex === GameMode.WATER_ALPHAS_PERIOD) {
            this.waterAlphaIndex = 0;
        }

        if (this.stageIndex === 5) {
            this.conveyorOffset = javaFloat(this.conveyorOffset + GameMode.CONVEYOR_SPEED);
            if (this.conveyorOffset >= 16) {
                this.conveyorOffset = javaFloat(this.conveyorOffset - 16);
            }
            let conveyorIndex = javaInt(this.conveyorOffset);
            this.conveyorDelta = javaFloat(conveyorIndex - this.conveyorLastIndex);
            if (this.conveyorDelta < 0) {
                this.conveyorDelta = javaFloat(this.conveyorDelta + 16);
            }
            this.tiles[0] = this.main.conveyors[conveyorIndex];
            this.conveyorLastIndex = conveyorIndex;
        }

        if (this.bossCameraPan && this.cameraY !== 0) {
            this.cameraY = javaFloat(this.cameraY - GameMode.BOSS_PAN_CAMERA_SPEED);
            if (this.cameraY <= 0) {
                this.maxCameraY = this.cameraY = 0;
                this.bossCameraPan = false;
                this.cameraPanListener.panComplete();
            } else {
                return;
            }
        }

        if (this.endingCameraPan) {
            if (this.cameraX > 512) {
                this.cameraX = javaFloat(this.cameraX - GameMode.ENDING_PAN_CAMERA_SPEED);
                if (this.cameraX <= 512) {
                    this.cameraX = 512;
                    this.endingCameraPan = false;
                    this.cameraPanListener.panComplete();
                } else {
                    return;
                }
            } else {
                this.cameraX = javaFloat(this.cameraX + GameMode.ENDING_PAN_CAMERA_SPEED);
                if (this.cameraX >= 512) {
                    this.cameraX = 512;
                    this.endingCameraPan = false;
                    this.cameraPanListener.panComplete();
                } else {
                    return;
                }
            }
        }

        this.processTriggers();

        let maxBoundY = javaFloat(this.maxCameraY + GameMode.REMOVE_BOUND);

        for (let i = 7; i >= 0; i--) {
            let list = this.elements[i];
            for (let j = list.size() - 1; j >= 0; j--) {
                let element = list.get(j);
                if (!element.removeFlag) {
                    element.checkBounds(maxBoundY);
                }
                if (!element.removeFlag) {
                    element.update();
                    if (element.changeLayerValue >= 0) {
                        if (element.layer !== element.changeLayerValue) {
                            element.layer = element.changeLayerValue;
                            list.removeAt(j);
                            this.elements[element.layer].add(element);
                        }
                        element.changeLayerValue = -1;
                    }
                }
                if (element.removeFlag) {
                    list.removeAt(j);
                    if (element.enemy) {
                        let enemy = element as Enemy;
                        this.enemies.removeValue(enemy);
                        if (enemy.solid) {
                            this.solids.removeValue(enemy);
                        }
                        if (enemy.mine) {
                            this.mines.removeValue(enemy);
                        }
                    }
                }
            }
        }

        if (this.playing) {
            this.player.update();
            // Player.update may synchronously replace this mode with Continue.
            if (this.main.mode !== this) {
                return;
            }
            this.cameraTrackPlayer();
        }

        if (this.stageCompletedFlag && this.stageCompletedDelay > 0 && --this.stageCompletedDelay === 0) {
            this.main.startFade(true, this);
        }
    }

GameMode.stageCompleted:
public stageCompleted(): void {
        this.stageCompletedFlag = true;
        this.main.stopAllSongs();
    }

GameMode.fadeCompleted:
public fadeCompleted(): void {
        if (this.stageIndex === 5) {
            this.main.requestMode(Modes.SUNSET, this.gc);
        } else {
            CutsceneSequence.requestCutscene(this.gc);
        }
    }

Player.update:
public update(): void {
        let tileType = this.gameMode.getTileType(this.x, this.y);
        this.inSwamp = tileType === TILE_TYPE_SWAMP;
        let speed = javaFloat(this.getSpeed());

        if (this.respawning > 0) {
            if (--this.respawning === 0) {
                if (this.main.extraLives > 0) {
                    this.main.loseLife();
                    this.invincible = Player.INVINCIBLE_DELAY;
                } else if (!this.gameMode.stageCompletedFlag) {
                    if (this.main.konamiCode !== null) {
                        this.main.konamiCode.enabled = false;
                    }
                    this.main.requestMode(Modes.CONTINUE, this.gameMode.gc);
                    // Continue owns the presentation; this outgoing Player must stop now.
                    return;
                }
            } else {
                return;
            }
        }

        if (tileType === TILE_TYPE_CONVEYOR) {
            let Y = javaFloat(javaFloat(this.y + Player.SENSOR_X) + Player.SPEED);
            if (
                this.gameMode.isDriveable(this.x, Y) &&
                this.gameMode.isDriveable(javaFloat(this.x - Player.SENSOR_Y), Y) &&
                this.gameMode.isDriveable(javaFloat(this.x + Player.SENSOR_Y), Y)
            ) {
                this.y = javaFloat(this.y + this.gameMode.conveyorDelta);
            }
        }

        this.targetAngle = -1;
        if (this.input.isDown() && this.input.isRight()) {
            // 45
            this.fireAngle = this.targetAngle = 45;
            this.lastTargetAngle = this.targetAngle;
            this.diagonalDelay = Player.DIAGONAL_DELAY;

            if (
                this.gameMode.isDriveable(javaFloat(this.x + Player.SENSOR_D_X0), javaFloat(this.y + Player.SENSOR_D_Y0)) &&
                this.gameMode.isDriveable(javaFloat(this.x + Player.SENSOR_D_X1), javaFloat(this.y + Player.SENSOR_D_Y1)) &&
                this.gameMode.isDriveable(javaFloat(this.x + Player.SENSOR_D_X2), javaFloat(this.y + Player.SENSOR_D_Y2))
            ) {
                this.x = javaFloat(this.x + speed);
                this.y = javaFloat(this.y + speed);
            }
        } else if (this.input.isDown() && this.input.isLeft()) {
            // 135
            this.fireAngle = this.targetAngle = 135;
            this.lastTargetAngle = this.targetAngle;
            this.diagonalDelay = Player.DIAGONAL_DELAY;

            if (
                this.gameMode.isDriveable(javaFloat(this.x - Player.SENSOR_D_X0), javaFloat(this.y + Player.SENSOR_D_Y0)) &&
                this.gameMode.isDriveable(javaFloat(this.x - Player.SENSOR_D_X1), javaFloat(this.y + Player.SENSOR_D_Y1)) &&
                this.gameMode.isDriveable(javaFloat(this.x - Player.SENSOR_D_X2), javaFloat(this.y + Player.SENSOR_D_Y2))
            ) {
                this.x = javaFloat(this.x - speed);
                this.y = javaFloat(this.y + speed);
            }
        } else if (this.input.isUp() && this.input.isLeft()) {
            // 225
            this.fireAngle = this.targetAngle = 225;
            this.lastTargetAngle = this.targetAngle;
            this.diagonalDelay = Player.DIAGONAL_DELAY;

            if (
                this.gameMode.isDriveable(javaFloat(this.x - Player.SENSOR_D_X0), javaFloat(this.y - Player.SENSOR_D_Y0)) &&
                this.gameMode.isDriveable(javaFloat(this.x - Player.SENSOR_D_X1), javaFloat(this.y - Player.SENSOR_D_Y1)) &&
                this.gameMode.isDriveable(javaFloat(this.x - Player.SENSOR_D_X2), javaFloat(this.y - Player.SENSOR_D_Y2))
            ) {
                this.x = javaFloat(this.x - speed);
                this.y = javaFloat(this.y - speed);
            }
        } else if (this.input.isUp() && this.input.isRight()) {
            // 315
            this.fireAngle = this.targetAngle = 315;
            this.lastTargetAngle = this.targetAngle;
            this.diagonalDelay = Player.DIAGONAL_DELAY;

            if (
                this.gameMode.isDriveable(javaFloat(this.x + Player.SENSOR_D_X0), javaFloat(this.y - Player.SENSOR_D_Y0)) &&
                this.gameMode.isDriveable(javaFloat(this.x + Player.SENSOR_D_X1), javaFloat(this.y - Player.SENSOR_D_Y1)) &&
                this.gameMode.isDriveable(javaFloat(this.x + Player.SENSOR_D_X2), javaFloat(this.y - Player.SENSOR_D_Y2))
            ) {
                this.x = javaFloat(this.x + speed);
                this.y = javaFloat(this.y - speed);
            }
        } else if (this.input.isRight()) {
            // 0
            this.fireAngle = 0;
            if ((this.lastTargetAngle === 45 || this.lastTargetAngle === 315) && this.diagonalDelay > 0) {
                this.diagonalDelay--;
            } else {
                this.targetAngle = 0;
                this.lastTargetAngle = this.targetAngle;
                this.diagonalDelay = 0;

                let X = javaFloat(javaFloat(this.x + Player.SENSOR_X) + Player.SPEED);
                if (
                    this.gameMode.isDriveable(X, this.y) &&
                    this.gameMode.isDriveable(X, javaFloat(this.y - Player.SENSOR_Y)) &&
                    this.gameMode.isDriveable(X, javaFloat(this.y + Player.SENSOR_Y))
                ) {
                    this.x = javaFloat(this.x + speed);
                }
            }
        } else if (this.input.isDown()) {
            // 90
            this.fireAngle = 90;
            if ((this.lastTargetAngle === 45 || this.lastTargetAngle === 135) && this.diagonalDelay > 0) {
                this.diagonalDelay--;
            } else {
                this.targetAngle = 90;
                this.lastTargetAngle = this.targetAngle;
                this.diagonalDelay = 0;

                let Y = javaFloat(javaFloat(this.y + Player.SENSOR_X) + Player.SPEED);
                if (
                    this.gameMode.isDriveable(this.x, Y) &&
                    this.gameMode.isDriveable(javaFloat(this.x - Player.SENSOR_Y), Y) &&
                    this.gameMode.isDriveable(javaFloat(this.x + Player.SENSOR_Y), Y)
                ) {
                    this.y = javaFloat(this.y + speed);
                }
            }
        } else if (this.input.isLeft()) {
            // 180
            this.fireAngle = 180;
            if ((this.lastTargetAngle === 135 || this.lastTargetAngle === 225) && this.diagonalDelay > 0) {
                this.diagonalDelay--;
            } else {
                this.targetAngle = 180;
                this.lastTargetAngle = this.targetAngle;
                this.diagonalDelay = 0;

                let X = javaFloat(javaFloat(this.x - Player.SENSOR_X) - Player.SPEED);
                if (
                    this.gameMode.isDriveable(X, this.y) &&
                    this.gameMode.isDriveable(X, javaFloat(this.y - Player.SENSOR_Y)) &&
                    this.gameMode.isDriveable(X, javaFloat(this.y + Player.SENSOR_Y))
                ) {
                    this.x = javaFloat(this.x - speed);
                }
            }
        } else if (this.input.isUp()) {
            // 270
            this.fireAngle = 270;
            if ((this.lastTargetAngle === 225 || this.lastTargetAngle === 315) && this.diagonalDelay > 0) {
                this.diagonalDelay--;
            } else {
                this.targetAngle = 270;
                this.lastTargetAngle = this.targetAngle;
                this.diagonalDelay = 0;

                let Y = javaFloat(javaFloat(this.y - Player.SENSOR_X) - Player.SPEED);
                if (
                    this.gameMode.isDriveable(this.x, Y) &&
                    this.gameMode.isDriveable(javaFloat(this.x - Player.SENSOR_Y), Y) &&
                    this.gameMode.isDriveable(javaFloat(this.x + Player.SENSOR_Y), Y)
                ) {
                    this.y = javaFloat(this.y - speed);
                }
            }
        } else {
            this.diagonalDelay = 0;
        }

        if (this.y > javaFloat(this.gameMode.maxCameraY + 928)) {
            this.y = javaFloat(this.gameMode.maxCameraY + 928);
        }

        if (this.angleSteps > 0) {
            if (--this.angleSteps === 0) {
                this.angle = this.nextAngle;
                this.displayAngle = javaFloat(this.nextAngle);
            } else {
                this.displayAngle = javaFloat(this.displayAngle + this.angleVelocity);
            }
        }

        if (this.angleSteps === 0 && this.targetAngle !== -1 && this.targetAngle !== this.angle) {
            this.angleSteps = Player.ANGLE_STEPS;
            if (this.targetAngle === 0) {
                if (this.angle >= 180) {
                    this.nextAngle = this.angle + 45;
                    if (this.nextAngle === 360) {
                        this.nextAngle = 0;
                    }
                    this.angleVelocity = Player.ANGLE_VELOCITY;
                } else {
                    this.nextAngle = this.angle - 45;
                    this.angleVelocity = -Player.ANGLE_VELOCITY;
                }
            } else if (this.targetAngle === 180) {
                if (this.angle > 180) {
                    this.nextAngle = this.angle - 45;
                    this.angleVelocity = -Player.ANGLE_VELOCITY;
                } else if (this.angle === 0) {
                    this.nextAngle = 315;
                    this.angleVelocity = -Player.ANGLE_VELOCITY;
                } else {
                    this.nextAngle = this.angle + 45;
                    this.angleVelocity = Player.ANGLE_VELOCITY;
                }
            } else if (this.targetAngle > 180) {
                if (this.angle < this.targetAngle && this.angle >= this.targetAngle - 180) {
                    this.nextAngle = this.angle + 45;
                    this.angleVelocity = Player.ANGLE_VELOCITY;
                } else {
                    this.nextAngle = this.angle - 45;
                    this.angleVelocity = -Player.ANGLE_VELOCITY;
                }
            } else {
                if (this.angle > this.targetAngle && this.angle <= this.targetAngle + 180) {
                    this.nextAngle = this.angle - 45;
                    this.angleVelocity = -Player.ANGLE_VELOCITY;
                } else {
                    this.nextAngle = this.angle + 45;
                    this.angleVelocity = Player.ANGLE_VELOCITY;
                }
            }
            if (this.nextAngle === -45) {
                this.nextAngle = 315;
            } else if (this.nextAngle === 360) {
                this.nextAngle = 0;
            }
        }

        if (
            this.targetAngle !== -1 &&
            !this.gameMode.bossCameraPan &&
            !this.gameMode.endingCameraPan &&
            this.gameMode.playing &&
            !this.gameMode.paused &&
            ++this.rumble === PLAYER_RUMBLE_STEPS
        ) {
            this.rumble = 0;
        }

        if (this.invincible > 0) {
            this.invincible--;
        }

        if (this.input.isFire()) {
            if (this.fireReleased && this.weaponArmed) {
                this.fireReleased = false;
                this.weaponArmed = false;
                if (this.targetAngle === -1 && this.angleSteps === 0) {
                    this.fireAngle = this.angle;
                }
                if (this.main.hasMissiles) {
                    new PlayerMissile(this.x, this.y, this.fireAngle, this.main.missilePower);
                } else {
                    new Grenade(this.x, this.y, this.fireAngle);
                }
            }
        } else {
            this.fireReleased = true;
        }

        if (this.gunArmed > 0) {
            this.gunArmed--;
        }
        if (this.input.isShoot()) {
            if (this.shootReleased || this.gunArmed === 0) {
                new PlayerBullet(this.x, this.y);
                this.gunArmed = Player.GUN_ARMED_DELAY;
            }
            this.shootReleased = false;
        } else {
            this.shootReleased = true;
            this.gunArmed = 0;
        }

        let invincibleLocal = this.invincible > 0;
        let xMargin = 32;
        let yMargin = 32;
        if (this.angle === 0 || this.angle === 180) {
            xMargin = 48;
        } else if (this.angle === 90 || this.angle === 270) {
            yMargin = 46;
        }
        for (let i = this.mines.size() - 1; i >= 0; i--) {
            let mine = this.mines.get(i);
            if (
                mine.bump(javaFloat(this.x - xMargin), javaFloat(this.y - yMargin), javaFloat(this.x + xMargin), javaFloat(this.y + yMargin), invincibleLocal)
            ) {
                if (!invincibleLocal) {
                    this.explode();
                    break;
                }
            }
        }
    }

Player.explode:
public explode(): void {
        if (this.gameMode.stageCompletedFlag) {
            return;
        }

        this.main.playSound(this.main.playerExplodeSound);
        if (this.main.extraLives === 0) {
            this.main.stopAllSongs();
        }
        Explosion.withPlayerExplosion(this.x, this.y, true);

        if (this.releaseablePows > 1) {
            let weaponCarrier = this.main.hasMissiles && this.main.random.nextInt(5) === 3;
            if (weaponCarrier) {
                this.releaseablePows++;
            }
            let release = this.releaseablePows - 2;
            if (release > 3) {
                release = 3;
            }
            for (let i = release; i >= 0; i--) {
                FriendlySoldier.wandering(
                    this.x,
                    this.y,
                    weaponCarrier && i === 0 ? FriendlySoldierType.WEAPON_CARRIER_WANDERER : FriendlySoldierType.WANDERER
                );
            }
        }
        this.pows = 0;
        this.releaseablePows = 0;
        this.main.missilePower = 0;
        this.main.hasMissiles = false;
        this.respawning = Player.RESPAWN_DELAY;
    }

BossSuperTank.update:
public update(): void {
        switch (this.state) {
            case BossSuperTank.STATE_APPEARING:
                if (--this.appearingDelay === 0) {
                    this.chooseTarget();
                    for (let i = 0; i < 5; i++) {
                        this.main.superTanks[0][i].setAlpha(1);
                    }
                }
                break;
            case BossSuperTank.STATE_ACCELERATING:
                this.vx = javaFloat(this.vx + this.ax);
                this.move(this.vx);
                if (this.ax < 0) {
                    if (this.vx <= -BossSuperTank.MAX_SPEED) {
                        this.state = BossSuperTank.STATE_MOVING;
                    }
                } else {
                    if (this.vx >= BossSuperTank.MAX_SPEED) {
                        this.state = BossSuperTank.STATE_MOVING;
                    }
                }
                break;
            case BossSuperTank.STATE_MOVING:
                this.move(this.vx);
                if (Math.abs(javaFloat(this.targetX - this.x)) <= BossSuperTank.ACCELERATION_DISTANCE) {
                    this.state = BossSuperTank.STATE_DECELERATING;
                }
                break;
            case BossSuperTank.STATE_DECELERATING:
                this.vx = javaFloat(this.vx - this.ax);
                this.move(this.vx);
                if (this.ax < 0) {
                    if (this.vx >= 0) {
                        this.stopMoving();
                    }
                } else {
                    if (this.vx <= 0) {
                        this.stopMoving();
                    }
                }
                break;
            case BossSuperTank.STATE_STOPPED:
                if (--this.delay === 0) {
                    this.chooseTarget();
                }
                break;
            case BossSuperTank.STATE_EXPLODING:
                if (--this.delay === 0) {
                    if (this.exploding + 1 < BossSuperTank.EXPLODING_TIME) {
                        Explosion.create(
                            javaFloat(this.x + this.main.random.nextInt(456)),
                            javaFloat(javaFloat(this.y + 32) + this.main.random.nextInt(230))
                        ).setDamagesEnemies(false);
                    }
                    this.delay = 8;
                }
                this.smashed = javaFloat(this.exploding * BossSuperTank.INV_EXPLODING_TIME);
                if (++this.exploding === BossSuperTank.EXPLODING_TIME) {
                    this.state = BossSuperTank.STATE_EXPLODING_FINISHING;
                    this.exploding = BossSuperTank.EXPLODING_FINISHING_TIME;
                }
                break;
            case BossSuperTank.STATE_EXPLODING_FINISHING:
                if (--this.exploding === 0) {
                    this.main.requestSong(this.main.cutsceneSong);
                    this.state = BossSuperTank.STATE_EXPLODED;
                    this.delay = 91;
                }
                break;
            case BossSuperTank.STATE_EXPLODED:
                if (--this.delay === 0) {
                    this.state = BossSuperTank.STATE_PANNING;
                    this.gameMode.startEndingCameraPan(this);
                }
                break;
        }
    }

BossSuperTank.kaboom:
private kaboom(): void {
        this.state = BossSuperTank.STATE_EXPLODING;
        this.main.stopAllSongs();
        this.main.playSoundAlways(this.main.headquartersExplodesSound);
        this.main.addPoints(this.points + 2000 * this.main.friendlySoldiersPickedUp);
        this.gameMode.destroyAllExcept(this);
        this.delay = 1;
        if (this.superFire !== null) {
            this.superFire.remove();
        }
    }

BossSuperTank.attack:
public override attack(x1: number, y1: number, x2: number, y2: number, attackSource: number): boolean {
        if (this.state >= BossSuperTank.STATE_EXPLODING) {
            return false;
        }
        if (attackSource === AttackSource.PLAYER_WEAPON && this.hitBounds(x1, y1, x2, y2)) {
            this.hits++;
            this.main.playHitExplodeSound();
            if (this.hits === BossSuperTank.HITS_EXPLODE) {
                this.kaboom();
            } else {
                this.displayHit(javaFloat(0.5 * javaFloat(x1 + x2)), javaFloat(0.5 * javaFloat(y1 + y2)));
                if (this.hits === BossSuperTank.HITS_ORANGE) {
                    this.colorIndex = 1;
                } else if (this.hits === BossSuperTank.HITS_RED) {
                    this.colorIndex = 2;
                }
            }
            return true;
        } else {
            return false;
        }
    }

Main.addPoints:
public addPoints(points: number): void {
        let before = this.score;
        this.score += points;
        if ((before < 20000 && this.score >= 20000) || javaIntDiv(before - 20000, 50000) !== javaIntDiv(this.score - 20000, 50000)) {
            this.gainExtraLife();
        }

        this.scoreStr = Main.formatScore(this.score);
    }

Main.gainExtraLife:
public gainExtraLife(): void {
        this.extraLives++;
        this.extraLivesStr = this.extraLives.toString();
        this.playSoundAlways(this.extraLifeSound);
    }
